package android.database.sqlite;
import android.database.Cursor;import android.content.ContentValues;import java.io.*;import java.util.*;
/** Test-only adapter. Every SQL statement is executed on one live Python SQLite connection. */
public final class SQLiteDatabase implements AutoCloseable {
 public interface CursorFactory {} public static final int CONFLICT_REPLACE=5;private final Process process;private final DataInputStream in;private final DataOutputStream out;private boolean transaction,successful,closed;
 public SQLiteDatabase(String path){try{String bridge=System.getProperty("queue.host.bridge");if(bridge==null)throw new IllegalStateException("Set queue.host.bridge");process=new ProcessBuilder("python3","-u",bridge,path).redirectError(ProcessBuilder.Redirect.INHERIT).start();in=new DataInputStream(process.getInputStream());out=new DataOutputStream(process.getOutputStream());}catch(IOException e){throw new SQLiteException("Bridge start failed",e);}}
 private static void bytes(DataOutputStream out,byte[] b)throws IOException{out.writeInt(b.length);out.write(b);}private static byte[] bytes(DataInputStream in)throws IOException{int n=in.readInt();if(n<0||n>16777216)throw new IOException("Invalid IPC length");byte[] b=new byte[n];in.readFully(b);return b;}
 private static void value(DataOutputStream o,Object v)throws IOException{if(v==null)o.writeByte(0);else if(v instanceof Number){if(!(v instanceof Integer||v instanceof Long||v instanceof Short||v instanceof Byte))throw new IllegalArgumentException("Unsupported numeric type");o.writeByte(1);o.writeLong(((Number)v).longValue());}else if(v instanceof String){o.writeByte(3);bytes(o,((String)v).getBytes(java.nio.charset.StandardCharsets.UTF_8));}else if(v instanceof byte[]){o.writeByte(4);bytes(o,(byte[])v);}else throw new IllegalArgumentException("Unsupported SQL parameter");}
 private static Object value(DataInputStream i)throws IOException{switch(i.readByte()){case 0:return null;case 1:return i.readLong();case 2:return i.readDouble();case 3:return new String(bytes(i),java.nio.charset.StandardCharsets.UTF_8);case 4:return bytes(i);default:throw new IOException("Invalid IPC type");}}
 private static final class Result {long changed,id;List<Object[]> rows=new ArrayList<>();}
 private synchronized Result execute(String sql,Object[] args){if(closed)throw new SQLiteException("Database closed");try{bytes(out,sql.getBytes(java.nio.charset.StandardCharsets.UTF_8));out.writeInt(args==null?0:args.length);if(args!=null)for(Object v:args)value(out,v);out.flush();int status=in.readInt();if(status!=0)throw new SQLiteException(new String(bytes(in),java.nio.charset.StandardCharsets.UTF_8));Result r=new Result();r.changed=in.readLong();r.id=in.readLong();int count=in.readInt(),columns=in.readInt();if(count<0||count>1000000||columns<0||columns>1000)throw new IOException("Invalid row bounds");for(int n=0;n<count;n++){Object[] row=new Object[columns];for(int c=0;c<columns;c++)row[c]=value(in);r.rows.add(row);}return r;}catch(IOException e){throw new SQLiteException("SQLite IPC failed",e);}}
 public void execSQL(String sql){execute(sql,null);}public void execSQL(String sql,Object[] args){execute(sql,args);}public Cursor rawQuery(String sql,String[] args){return new Rows(execute(sql,args).rows);}
 public void setForeignKeyConstraintsEnabled(boolean b){if(transaction)throw new IllegalStateException("Foreign keys in transaction");execSQL("PRAGMA foreign_keys="+(b?"ON":"OFF"));}
 public void beginTransaction(){if(transaction)throw new UnsupportedOperationException("Nested transactions are not implemented");execSQL("BEGIN EXCLUSIVE");transaction=true;successful=false;}
 public void setTransactionSuccessful(){if(!transaction||successful)throw new IllegalStateException("No pending transaction");successful=true;}
 public void endTransaction(){if(!transaction)throw new IllegalStateException("No transaction");try{execSQL(successful?"COMMIT":"ROLLBACK");}finally{transaction=false;successful=false;}}
 private static String name(String n){if(!n.matches("[A-Za-z_][A-Za-z0-9_]*"))throw new IllegalArgumentException("Unsupported SQL identifier");return "\""+n+"\"";}
 public int update(String table,ContentValues values,String where,String[] args){List<Object> parameters=new ArrayList<>();StringJoiner sets=new StringJoiner(",");for(Map.Entry<String,Object> e:values.valueSet()){sets.add(name(e.getKey())+"=?");parameters.add(e.getValue());}if(values.size()==0)throw new IllegalArgumentException("Empty update");if(args!=null)Collections.addAll(parameters,args);return (int)execute("UPDATE "+name(table)+" SET "+sets+(where==null?"":" WHERE "+where),parameters.toArray()).changed;}
 public int delete(String table,String where,String[] args){return (int)execute("DELETE FROM "+name(table)+(where==null?"":" WHERE "+where),args).changed;}
 public long insertOrThrow(String table,String nullColumnHack,ContentValues values){return insert(table,nullColumnHack,values,false);}
 public long insertWithOnConflict(String table,String nullColumnHack,ContentValues values,int conflict){if(conflict!=CONFLICT_REPLACE)throw new UnsupportedOperationException("Only REPLACE supported");return insert(table,nullColumnHack,values,true);}
 private long insert(String table,String hack,ContentValues values,boolean replace){if(hack!=null||values.size()==0)throw new UnsupportedOperationException("Empty/null-column insert unsupported");StringJoiner keys=new StringJoiner(","),slots=new StringJoiner(",");List<Object> args=new ArrayList<>();for(Map.Entry<String,Object> e:values.valueSet()){keys.add(name(e.getKey()));slots.add("?");args.add(e.getValue());}return execute("INSERT "+(replace?"OR REPLACE ":"")+"INTO "+name(table)+" ("+keys+") VALUES ("+slots+")",args.toArray()).id;}
 public int getVersion(){try(Cursor c=rawQuery("PRAGMA user_version",null)){c.moveToFirst();return c.getInt(0);}}public void setVersion(int version){if(version<0)throw new IllegalArgumentException();execSQL("PRAGMA user_version="+version);}
 public synchronized void close(){if(closed)return;try{out.close();if(!process.waitFor(5,java.util.concurrent.TimeUnit.SECONDS)){process.destroyForcibly();throw new SQLiteException("Bridge close timeout");}if(process.exitValue()!=0)throw new SQLiteException("Bridge failed during close");}catch(IOException|InterruptedException e){throw new SQLiteException("Close failed",e);}finally{closed=true;}}
 private static final class Rows implements Cursor {final List<Object[]> rows;int position=-1;boolean closed;Rows(List<Object[]> r){rows=r;}private Object at(int i){if(closed||position<0||position>=rows.size())throw new IllegalStateException("Cursor position");return rows.get(position)[i];}public boolean moveToFirst(){if(closed)throw new IllegalStateException("Cursor closed");position=0;return !rows.isEmpty();}public boolean moveToNext(){if(closed)throw new IllegalStateException("Cursor closed");position++;return position<rows.size();}public long getLong(int i){Object v=at(i);return v==null?0:((Number)v).longValue();}public int getInt(int i){return (int)getLong(i);}public String getString(int i){Object v=at(i);return v==null?null:v.toString();}public byte[] getBlob(int i){return (byte[])at(i);}public boolean isNull(int i){return at(i)==null;}public int getType(int i){Object v=at(i);return v==null?0:v instanceof Long?1:v instanceof Double?2:v instanceof String?3:v instanceof byte[]?4:-1;}public void close(){closed=true;}}
}
